using System;
using System.Collections.Generic;
using UnityEngine;

// ---- Level data (Assets/Resources/Level/level.json, generated by Tools/art/level.py) ----
[Serializable] public class LvRect { public float x, y, w, h; }
[Serializable] public class LvPoint { public float x, y; }
[Serializable] public class LvProp { public float x, y; public int v; }
[Serializable] public class LvEnemy { public string type; public float x, y; }
[Serializable]
public class LevelData
{
    public LvRect bounds;
    public LvPoint playerStart, bossSpawn, roomEntry, door, doorExit, pyramid;
    public List<LvRect> water, pits, solid, pyramidBody;
    public List<LvEnemy> enemies;
    public List<LvProp> trees, bushes, rocks, mushrooms, skulls, torches, pillars;
}

/// <summary>Marks the colliders of water and pits (so enemies can "see" across them).</summary>
public class HazardCollider : MonoBehaviour { }

/// <summary>
/// Builds the whole level at runtime from level.json: painted ground, rivers, lake, pits, trees, bushes, rocks,
/// torches, the pyramid with its door, the boss chamber and every enemy. The Game scene only needs a camera,
/// the player and GameBootstrap, so the level can be edited just by regenerating the JSON / PNGs.
/// </summary>
[DefaultExecutionOrder(-300)]
public class LevelBuilder : MonoBehaviour
{
    public static LevelData Data { get; private set; }
    public static Rect Bounds { get; private set; }

    Transform root;
    Sprite waterA, waterB;

    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
    static void ResetStatics() { Data = null; }

    void Awake()
    {
        var asset = Resources.Load<TextAsset>("Level/level");
        if (asset == null) { Debug.LogError("[Mictlan] Missing Assets/Resources/Level/level.json"); return; }
        Data = JsonUtility.FromJson<LevelData>(asset.text);
        Bounds = new Rect(Data.bounds.x, Data.bounds.y, Data.bounds.w, Data.bounds.h);
        Hazards.Clear();
        root = new GameObject("Level").transform;
        Build();
    }

    void Build()
    {
        SetupCameraAndPlayer();
        BuildGround();
        BuildColliders();
        BuildProps();
        BuildPyramid();
        SpawnEnemies();
        if (GameProgress.KeyDropped && !GameProgress.HasKey) KeyPickup.Spawn(GameProgress.KeyPosition);
        gameObject.AddComponent<Darkness>();
    }

    // ------------------------------------------------------------------ camera / player
    void SetupCameraAndPlayer()
    {
        var follow = FindFirstObjectByType<CameraFollow2D>();
        if (follow != null)
        {
            follow.bounds = Bounds;
            follow.useBounds = true;
            var cam = follow.GetComponent<Camera>();
            cam.backgroundColor = new Color(0.02f, 0.02f, 0.04f);
        }
        var player = FindFirstObjectByType<Player2D>();
        if (player != null)
        {
            var start = new Vector2(Data.playerStart.x, Data.playerStart.y);
            player.Teleport(start);
            var stats = player.GetComponent<PlayerCombatStats>();
            if (stats != null) stats.SetCheckpoint(start);
            if (follow != null) follow.SnapToTarget();
        }
    }

    // ------------------------------------------------------------------ ground / water
    void BuildGround()
    {
        var g = NewSprite("Ground", SpriteLib.Single("ground"), Bounds.center, -32000);
        g.transform.SetParent(root, false);

        waterA = SpriteLib.Single("water_0");
        waterB = SpriteLib.Single("water_1");
        var w = NewSprite("WaterShimmer", waterA, Bounds.center, -31900);
        w.transform.SetParent(root, false);
        w.AddComponent<SpriteFlipper>().Init(w.GetComponent<SpriteRenderer>(), waterA, waterB, 0.7f);
    }

    // ------------------------------------------------------------------ colliders
    void BuildColliders()
    {
        foreach (var r in Data.water) MakeBox("Water", r, TerrainKind.Water, true);
        foreach (var r in Data.pits) MakeBox("Pit", r, TerrainKind.Pit, true);
        foreach (var r in Data.solid) MakeBox("Cliff", r, TerrainKind.Ground, false);
        foreach (var r in Data.pyramidBody) MakeBox("PyramidBody", r, TerrainKind.Ground, false);
    }

    void MakeBox(string name, LvRect r, TerrainKind kind, bool hazard)
    {
        var go = new GameObject(name);
        go.transform.SetParent(root, false);
        go.transform.position = new Vector3(r.x + r.w * 0.5f, r.y + r.h * 0.5f, 0f);
        var col = go.AddComponent<BoxCollider2D>();
        col.size = new Vector2(r.w, r.h);
        if (hazard)
        {
            go.AddComponent<HazardCollider>();
            Hazards.Add(kind, new Rect(r.x, r.y, r.w, r.h), col);
        }
    }

    // ------------------------------------------------------------------ props
    void BuildProps()
    {
        string[] treeNames = { "tree_a", "tree_b", "tree_c" };
        foreach (var t in Data.trees)
            Prop(treeNames[Mathf.Abs(t.v) % 3], new Vector2(t.x, t.y), new Vector2(0.7f, 0.4f), new Vector2(0f, 0.2f));
        foreach (var b in Data.bushes)
            Prop(b.v == 0 ? "bush_a" : "bush_b", new Vector2(b.x, b.y), Vector2.zero, Vector2.zero);
        string[] rockNames = { "rock_s", "rock_m", "rock_l" };
        Vector2[] rockSizes = { new Vector2(0.5f, 0.3f), new Vector2(0.9f, 0.45f), new Vector2(1.6f, 0.8f) };
        foreach (var r in Data.rocks)
        {
            int v = Mathf.Clamp(r.v, 0, 2);
            Prop(rockNames[v], new Vector2(r.x, r.y), rockSizes[v], new Vector2(0f, rockSizes[v].y * 0.5f));
        }
        foreach (var s in Data.skulls) Prop("skulls", new Vector2(s.x, s.y), Vector2.zero, Vector2.zero);
        foreach (var m in Data.mushrooms)
        {
            Prop("mushroom", new Vector2(m.x, m.y), Vector2.zero, Vector2.zero);
            var gl = NewSprite("MushroomGlow", SpriteLib.Single("glow"), new Vector2(m.x, m.y + 0.3f), -30900);
            gl.transform.SetParent(root, false);
            gl.GetComponent<SpriteRenderer>().color = new Color(0.3f, 0.9f, 1f, 0.45f);
            gl.transform.localScale = Vector3.one * 0.8f;
        }
        foreach (var p in Data.pillars)
        {
            var go = Prop("rock_l", new Vector2(p.x, p.y), new Vector2(1.6f, 0.9f), new Vector2(0f, 0.45f));
            go.transform.localScale = new Vector3(1.1f, 2.2f, 1f);
        }
        foreach (var t in Data.torches) Torch(new Vector2(t.x, t.y));
    }

    GameObject Prop(string spriteName, Vector2 pos, Vector2 colliderSize, Vector2 colliderOffset)
    {
        var go = new GameObject(spriteName);
        go.transform.SetParent(root, false);
        go.transform.position = pos;
        var child = new GameObject("Sprite");
        child.transform.SetParent(go.transform, false);
        var sr = child.AddComponent<SpriteRenderer>();
        sr.sprite = SpriteLib.Single(spriteName, new Vector2(0.5f, 0.08f));
        if (colliderSize != Vector2.zero)
        {
            var col = go.AddComponent<BoxCollider2D>();
            col.size = colliderSize;
            col.offset = colliderOffset;
        }
        var ys = go.AddComponent<YSort>();
        ys.isStatic = true;
        return go;
    }

    void Torch(Vector2 pos)
    {
        var go = new GameObject("Torch");
        go.transform.SetParent(root, false);
        go.transform.position = pos;
        var sr = go.AddComponent<SpriteRenderer>();
        var a = SpriteLib.Single("torch_0", new Vector2(0.5f, 0.1f));
        var b = SpriteLib.Single("torch_1", new Vector2(0.5f, 0.1f));
        sr.sprite = a;
        sr.sortingOrder = -Mathf.RoundToInt(pos.y * 100f);
        go.AddComponent<SpriteFlipper>().Init(sr, a, b, 0.18f);

        var glow = NewSprite("Glow", SpriteLib.Single("glow"), pos + Vector2.up * 0.7f, 7000);
        glow.transform.SetParent(go.transform, true);
        glow.transform.localScale = Vector3.one * 3.2f;
        glow.GetComponent<SpriteRenderer>().color = new Color(1f, 0.55f, 0.2f, 0.55f);
        glow.AddComponent<GlowPulse>();
        // no collider: torches are decoration
        var col = go.AddComponent<BoxCollider2D>();
        col.size = new Vector2(0.3f, 0.2f);
    }

    // ------------------------------------------------------------------ pyramid + boss chamber
    void BuildPyramid()
    {
        var p = new Vector2(Data.pyramid.x, Data.pyramid.y);
        var pyr = NewSprite("Pyramid", SpriteLib.Single("pyramid", new Vector2(0.5f, 0f)), p, -29000);
        pyr.transform.SetParent(root, false);

        var door = new GameObject("PyramidDoor");
        door.transform.SetParent(root, false);
        door.transform.position = new Vector3(Data.door.x, Data.door.y, 0f);
        door.AddComponent<PyramidDoor>();

        Vector2 entry = new Vector2(Data.roomEntry.x, Data.roomEntry.y);
        BossRoom.Setup(entry, new Vector2(Data.doorExit.x, Data.doorExit.y));

        var exit = NewSprite("RoomExit", SpriteLib.Single("door_open"), entry + new Vector2(-2.6f, 0f), -30000);
        exit.transform.SetParent(root, false);
        exit.AddComponent<RoomExit>();
    }

    // ------------------------------------------------------------------ enemies
    void SpawnEnemies()
    {
        foreach (var e in Data.enemies) SpawnEnemy(e.type, new Vector2(e.x, e.y));
        SpawnEnemy("Quetzalcoatl", new Vector2(Data.bossSpawn.x, Data.bossSpawn.y));
    }

    void SpawnEnemy(string type, Vector2 pos)
    {
        var prefab = Resources.Load<GameObject>("Enemies/Enemy_" + type);
        if (prefab == null) { Debug.LogError($"[Mictlan] Missing prefab Resources/Enemies/Enemy_{type}. Use menu Mictlan > Rebuild Scenes."); return; }
        var go = Instantiate(prefab, new Vector3(pos.x, pos.y, 0f), Quaternion.identity);
        go.name = "Enemy_" + type;
    }

    // ------------------------------------------------------------------ helpers
    static GameObject NewSprite(string name, Sprite sprite, Vector2 pos, int order)
    {
        var go = new GameObject(name);
        go.transform.position = pos;
        var sr = go.AddComponent<SpriteRenderer>();
        sr.sprite = sprite;
        sr.sortingOrder = order;
        return go;
    }
}

/// <summary>Swaps between two sprites on a timer (water ripples, torch flames).</summary>
public class SpriteFlipper : MonoBehaviour
{
    SpriteRenderer sr; Sprite a, b; float interval, t; bool flip;
    public void Init(SpriteRenderer renderer, Sprite first, Sprite second, float seconds)
    { sr = renderer; a = first; b = second; interval = seconds; t = UnityEngine.Random.value * seconds; }
    void Update()
    {
        if (sr == null) return;
        t += Time.deltaTime;
        if (t >= interval) { t = 0f; flip = !flip; sr.sprite = flip ? b : a; }
    }
}

/// <summary>Soft flicker for torch light sprites.</summary>
public class GlowPulse : MonoBehaviour
{
    SpriteRenderer sr; float baseScale, seed;
    void Awake() { sr = GetComponent<SpriteRenderer>(); baseScale = transform.localScale.x; seed = UnityEngine.Random.value * 10f; }
    void Update()
    {
        float k = 1f + 0.12f * Mathf.Sin(Time.time * 7f + seed) + 0.06f * Mathf.Sin(Time.time * 13f + seed * 2f);
        transform.localScale = Vector3.one * baseScale * k;
    }
}
